export interface GitActionResultNotification {
  readonly type: "success" | "error";
  readonly title: string;
  readonly description?: string;
  readonly prUrl?: string;
}

const RESULT_DISMISS_MS = 5_000;

const gitActionResultCell: { value: GitActionResultNotification | null } = { value: null };
let dismissTimer: ReturnType<typeof setTimeout> | null = null;

function broadcast(result: GitActionResultNotification | null): void {
  gitActionResultCell.value = result;
}

export function showGitActionResult(result: GitActionResultNotification): void {
  if (dismissTimer) clearTimeout(dismissTimer);
  broadcast(result);
  dismissTimer = setTimeout(() => {
    dismissTimer = null;
    broadcast(null);
  }, RESULT_DISMISS_MS);
}

export function dismissGitActionResult(): void {
  if (dismissTimer) clearTimeout(dismissTimer);
  dismissTimer = null;
  broadcast(null);
}

export function useGitActionResultNotification(): {
  readonly result: GitActionResultNotification | null;
  readonly dismiss: () => void;
} {
  return { result: gitActionResultCell.value, dismiss: dismissGitActionResult };
}

import type { MessageId, RunId } from "@t3tools/contracts";

export interface QueuedRunEdit {
  readonly runId: RunId;
  readonly messageId: MessageId;
  readonly originalText: string;
  /** Removing a server attachment changes the message even when the draft looks untouched. */
  readonly removedExistingAttachment?: true;
}

const queuedRunEdits = new Map<string, QueuedRunEdit>();

export const getQueuedRunEdit = (threadKey: string): QueuedRunEdit | null => queuedRunEdits.get(threadKey) ?? null;

function exitQueuedRunEdit(threadKey: string, edit: QueuedRunEdit): void {
  Promise.resolve(edit.originalText).catch((error: unknown) => {
    console.warn("[queued-run-edit] could not persist the recovered edit", error);
  });
  queuedRunEdits.delete(threadKey);
}

export function beginQueuedRunEdit(threadKey: string, edit: QueuedRunEdit): void {
  const previous = getQueuedRunEdit(threadKey);
  if (previous !== null && previous.runId !== edit.runId) exitQueuedRunEdit(threadKey, previous);
  queuedRunEdits.set(threadKey, edit);
}

